parameters.jsCode:
/**
 * Appointment Reminder Logic
 * Detects which reminders (48h / 24h / 2h) need to be sent
 * Updates flags used by Filter node downstream.
 *
 * Expected sheet columns:
 * Date | Time | Patient Name | Phone | Email | Appointment Type | Confirmed? | 48h_sent | 24h_sent | 2h_sent | Staff_Alerted
 */

const now = new Date();
const results = [];

function parseAppointment(dateStr, timeStr) {
  // Support both ISO (YYYY-MM-DD) and US-style (MM/DD/YYYY)
  try {
    if (dateStr.includes('-')) return new Date(`${dateStr}T${timeStr}`);
    const [m, d, y] = dateStr.split('/');
    return new Date(`${y}-${m}-${d}T${timeStr}`);
  } catch {
    return null;
  }
}

for (const item of $input.all()) {
  const row = item.json;
  const { Date: dateStr, Time: timeStr, Email } = row;
  if (!dateStr || !timeStr || !Email) continue;

  const appt = parseAppointment(dateStr, timeStr);
  if (!appt || isNaN(appt)) continue;

  const hoursUntil = (appt - now) / 36e5;
  const confirmed = (row["Confirmed?"] || "").toLowerCase();

  // Skip confirmed or past appointments
  if (confirmed === "yes" || confirmed === "confirmed" || hoursUntil < 0) continue;

  // Determine which reminder(s) to send
  const shouldSend48h = hoursUntil >= 47 && hoursUntil < 49 && row["48h_sent"] !== "Yes";
  const shouldSend24h = hoursUntil >= 23 && hoursUntil < 25 && row["24h_sent"] !== "Yes";
  const shouldSend2h  = hoursUntil >= 1  && hoursUntil < 3  && row["2h_sent"]  !== "Yes";
  const shouldAlertStaff = hoursUntil < 1 && (row["Staff_Alerted"] !== "Yes") && (confirmed === "no" || !confirmed);

  // Only push rows needing an action
  if (shouldSend48h || shouldSend24h || shouldSend2h || shouldAlertStaff) {
    results.push({
      json: {
        ...row,
        hoursUntil,
        shouldSend48h,
        shouldSend24h,
        shouldSend2h,
        shouldAlertStaff,
        formattedDate: appt.toLocaleDateString("en-US", {
          weekday: "long",
          month: "long",
          day: "numeric"
        }),
        formattedTime: appt.toLocaleTimeString("en-US", {
          hour: "numeric",
          minute: "2-digit",
          hour12: true
        })
      }
    });
  }
}

console.log(`✅ Processed ${results.length} appointments needing reminders.`);
return results;
